"""Follow-up incoming moves in road chapter (ch9) must not hide arrived units (#4851).

Live g1190-ch1v4 ch9 (41-x): generals moved from イソ -> イデ！ back-to-back.
Because every follow-up move kept ``routes.incoming(mem, 'イデ！')`` non-empty,
``routes.arrival_probe_due(mem, 'イデ！', cooldown=True)`` stayed False and
``イデ！`` stayed at its stale 1-general garrison record without launching boss
waves.
"""
from docich.hanjuku_speedrun.hanjuku.strategy import routes


def _mem(chapter, tick, sorties, *, last_read=None, asked=None):
    return {
        'chapter': chapter,
        'tick': tick,
        'route_probe_read_tick': {} if last_read is None else last_read,
        'arrival_probe_tick': {} if asked is None else asked,
        'world': {
            'sorties': sorties,
            'launched_orders': {},
        },
    }


def test_non_road_incoming_still_waits_for_busy_window():
    mem = _mem(
        chapter=5,
        tick=2000,
        sorties={
            'A:1:M1': {'purpose': 'move', 'source': 'アルマムーン', 'target': 'アイアイエー',
                       'general': 'ゼウス', 'status': 'overdue', 'tick': 1000},
            'A:1:M2': {'purpose': 'move', 'source': 'アルマムーン', 'target': 'アイアイエー',
                       'general': 'ヴィーナス', 'status': 'en_route', 'tick': 1950},
        },
    )
    assert routes.arrival_probe_due(mem, 'アイアイエー', cooldown=True) is False


def test_road_chapter_probes_after_delay_even_while_followup_moves_are_incoming():
    mem = _mem(
        chapter=9,
        tick=750150,
        sorties={
            'A:3814542a:Mf0523b': {'purpose': 'move', 'source': 'イソ', 'target': 'イデ！',
                                   'general': 'バトウラ', 'status': 'en_route', 'tick': 749600},
            'A:3814542a:M1f8bbe': {'purpose': 'move', 'source': 'イソ', 'target': 'イデ！',
                                   'general': 'フェデリーニ', 'status': 'en_route', 'tick': 750100},
        },
        last_read={'イデ！': 692973},
        asked={'イデ！': 692973},
    )
    assert routes.arrival_probe_due(mem, 'イデ！', cooldown=True) is True

    # Respects PROBE_INTERVAL cooldown when just probed.
    mem['arrival_probe_tick']['イデ！'] = 750130
    assert routes.arrival_probe_due(mem, 'イデ！', cooldown=True) is False
    assert routes.arrival_probe_due(mem, 'イデ！', cooldown=False) is True

    # Does not probe before ROAD_ARRIVAL_PROBE_DELAY has passed on any dispatch.
    mem2 = _mem(
        chapter=9,
        tick=750150,
        sorties={
            'A:3814542a:M1f8bbe': {'purpose': 'move', 'source': 'イソ', 'target': 'イデ！',
                                   'general': 'フェデリーニ', 'status': 'en_route', 'tick': 750050},
        },
    )
    assert routes.arrival_probe_due(mem2, 'イデ！', cooldown=True) is False
